  // ---------- tree atlas ----------
  const BLK = [["data:image/png;base64,", 128, 113], ["data:image/png;base64,", 128, 113], ["data:image/png;base64,", 128, 113], ["data:image/png;base64,", 128, 113]].map(([s,w,h]) => ({ im: Object.assign(new Image(), { src: s }), w, h }));
  const TRE = [["data:image/png;base64,", 90, 118], ["data:image/png;base64,", 99, 118], ["data:image/png;base64,", 99, 118], ["data:image/png;base64,", 84, 118], ["data:image/png;base64,", 90, 118], ["data:image/png;base64,", 99, 118], ["data:image/png;base64,", 99, 118], ["data:image/png;base64,", 84, 118]].map(([s,w,h]) => ({ im: Object.assign(new Image(), { src: s }), w, h }));
  const R = [[0, 0, 77, 93]];   // ground.png: dark tile at x=0, light tile at x=32 (32x16 top faces from the hernandack pack)

  // ---------- cozy home + campfire ----------
  const HOME = new Image(); HOME.src = ART.buildingData('cabin');
  const HOME_N = 3, HOME_C = 21, HOME_R = 18;     // cabin sits on a 3x3 block of slots (cols 21-23, rows 18-20)
  const NAME = { tree: 'Oak tree', home: 'Cozy cabin', fire: 'Campfire' };
  const SUB = { tree: 'Clear it to make room', home: 'Your home', fire: 'Warm and glowing' };
  let home = { c: HOME_C, r: HOME_R };            // top-left slot of the cabin; changes when the player moves it
  let drag = null;                                // { id, c, r, oc, or, ok } while the cabin is being carried

  // ---------- world ----------
  const spawn = { x: WORLD_W / 2, y: WORLD_H / 2 };   // player spawn: centre of the clearing, on the checker
  const clearing = { x0: spawn.x - HALF_W, y0: spawn.y - HALF_H, x1: spawn.x + HALF_W, y1: spawn.y + HALF_H };
  const trees = [];

  // Keep the clearing open. Trees are upright sprites, so on screen a tree's canopy rises
  // above its base; in world terms that is back toward smaller x and y. Check the base and
  // two points up the canopy. `shrink` lets some trees creep in so the edge is ragged.
  function inClearing(x, y, r, h, shrink) {
    const d = h * .8;
    for (const t of [0, .5, 1]) {
      const px = x - t * d, py = y - t * d;
      if (px > clearing.x0 - r + shrink && px < clearing.x1 + r - shrink &&
          py > clearing.y0 - r + shrink && py < clearing.y1 + r - shrink) return true;
    }
    return false;
  }
  // Everything lives in slots. `occ` maps "col,row" to whatever stands on that square (a tree for now;
  // buildings, farms and so on go in the same map later). Trees fill most squares, one tree per slot.
  const occ = new Map();
  const slot = (c, r) => c + ',' + r;
  const EMPTY_CHANCE = .22;             // fraction of forest squares left empty: 0 = solid wall of trees, .5 = open woodland
  function growForest() {
    const cols = WORLD_W / CELL, rows = WORLD_H / CELL;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        if (rng() < EMPTY_CHANCE) continue;
        const x = (c + .5) * CELL, y = (r + .5) * CELL;
        if (inClearing(x, y, R[0][2] * .7, R[0][3], 0)) continue;     // keep the clearing open
        const t = { type: 'tree', x, y, c, r, v: (rng() * TRE.length) | 0, s: rr(.85, 1.1), flip: rng() < .5 ? -1 : 1, ph: rr(0, 6.28) };
        trees.push(t); occ.set(slot(c, r), t);
      }
    }
    const claim = (c, r, o) => { const old = occ.get(slot(c, r)); if (old) { const k = trees.indexOf(old); if (k >= 0) trees.splice(k, 1); } occ.set(slot(c, r), o); };
    try { const s = JSON.parse(localStorage.getItem('homePos') || 'null'); if (s && Number.isInteger(s.c) && Number.isInteger(s.r) && homeOK(s.c, s.r, true)) home = { c: s.c, r: s.r }; } catch (e) {}
    for (let j = 0; j < HOME_N; j++) for (let i = 0; i < HOME_N; i++) claim(home.c + i, home.r + j, { type: 'home', c: home.c + i, r: home.r + j });
    for (const f of farms) claimFarmSlots(f);   // farms the player already placed take their own tiles
    trees.sort((a, b) => (a.x + a.y) - (b.x + b.y) || a.x - b.x);   // far to near in the diamond view
  }

